import heapq
def mergeKLists(lists):
    h = []
    for i, n in enumerate(lists):
        if n:
            heapq.heappush(h, (n.val, i, n))
    dummy = cur = ListNode(0)
    while h:
        v, i, n = heapq.heappop(h)
        cur.next = n
        cur = n
        if n.next:
            heapq.heappush(h, (n.next.val, i, n.next))
    return dummy.next

